# owner: platform
import unittest

from hourglass.models import Span
from hourglass.rounding import label_spans

class LabelTests(unittest.TestCase):
    def test_rounds_ends_to_nearest_step(self):
        labels = label_spans([Span(541, 1036)], 15)
        self.assertEqual(labels, ["09:00-17:15 (8h 15m)"])

    def test_halfway_rounds_up(self):
        labels = label_spans([Span(545, 1035)], 10)
        self.assertEqual(labels, ["09:10-17:20 (8h 10m)"])

    def test_keeps_span_order(self):
        spans = [Span(540, 600), Span(700, 760)]
        expected = [
            "09:00-10:00 (1h 0m)",
            "12:00-13:00 (1h 0m)"
        ]
        self.assertEqual(label_spans(spans, 60), expected)

    def test_end_of_day_is_labelled_24_00(self):
        labels = label_spans([Span(1430, 1440)], 15)
        self.assertEqual(labels, ["23:45-24:00 (0h 15m)"])

    def test_collapsed_span_is_labelled_zero(self):
        labels = label_spans([Span(541, 544)], 15)
        self.assertEqual(labels, ["09:00-09:00 (0h 0m)"])

    def test_empty(self):
        self.assertEqual(label_spans([], 15), [])

class StepTests(unittest.TestCase):
    def test_steps_that_divide_an_hour(self):
        for step in (1, 5, 6, 10, 12, 15, 20, 30, 60):
            with self.subTest(step=step):
                self.assertEqual(label_spans([], step), [])

    def test_bad_steps_raise(self):
        for step in (0, -15, 7, 25, 120, 2.5):
            with self.subTest(step=step):
                with self.assertRaises(ValueError):
                    label_spans([Span(540, 600)], step)
